from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
data=json.loads((R/'source/model-data.json').read_text());assert data['parameters']['revision'].startswith('v0.3.2-')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>MakerWorld CAD 展示图 · v0.3.2</title><style>
*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;background:#d7ddd5}nav{height:48px;display:flex;align-items:center;gap:12px;padding:8px 25px;font-size:13px}button{border:1px solid #9ca99f;border-radius:5px;background:#f8faf6;padding:5px 15px;cursor:pointer}#sheet{position:relative;width:1600px;height:1200px;background:#e8e9e4;overflow:hidden}canvas{display:block;position:absolute;inset:0}header{position:absolute;left:80px;right:80px;top:58px;pointer-events:none}.eyebrow{font-size:13px;letter-spacing:.2em;color:#69756e}h1{font-size:40px;font-weight:600;letter-spacing:.03em;line-height:1.3;margin:13px 0 10px;color:#26332e}.subtitle{font-size:21px;letter-spacing:.015em;color:#63766b}.badge{position:absolute;right:0;top:12px;font-size:16px;border:1px solid #a2afa5;color:#52695b;padding:8px 15px;border-radius:5px;background:#e8ece5bb}.bottom{position:absolute;left:80px;right:80px;bottom:44px;pointer-events:none}.metrics{display:flex;justify-content:center;gap:18px;margin-bottom:31px}.metrics span{font-size:18px;letter-spacing:.025em;color:#455c4d;background:#f6f8f0dd;border:1px solid #bdcbbd;border-radius:6px;padding:9px 18px}.note{font-size:16px;color:#69796c;letter-spacing:.025em;padding-top:16px;border-top:1px solid #bdc8bb;text-align:center}
</style><nav><button data-mode="front-structure">结构封面</button><button data-mode="front-equipped">设备装配</button><button data-mode="rear">背部开放</button><button data-mode="inside">内部结构</button><span>所有画面使用同一份 v0.3.2 CAD 网格；未实物打印验证。</span></nav><div id="sheet"><canvas></canvas><header><div class="eyebrow">DESKTOP AUDIO RACK / v0.3.2</div><h1></h1><div class="subtitle"></div><div class="badge"></div></header><div class="bottom"><div class="metrics"></div><div class="note"></div></div></div><script id="cad-data" type="application/json">__DATA__</script><script>__JS__</script><script>for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>window.makerworldRender.setView(b.dataset.mode);</script></html>'''
page=page.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')).replace('__JS__',(R/'source/makerworld-render.bundle.js').read_text().replace('</script','<\\/script'))
(R/'renders/makerworld-v0.3.2.html').write_text(page)
print('Built 1600x1200 CAD renderer')
